package ru.neverland.mintexpeditions.command;
import org.bukkit.command.*; import ru.neverland.mintexpeditions.MintTownyExpeditions; import ru.neverland.mintexpeditions.model.*; import ru.neverland.mintexpeditions.service.*; import java.util.*;
public final class AdminCommand implements CommandExecutor,TabCompleter {private final MintTownyExpeditions plugin;public AdminCommand(MintTownyExpeditions p){plugin=p;}public boolean onCommand(CommandSender s,Command c,String l,String[] args){if(!s.hasPermission("mintexpeditions.admin")){plugin.messages().send(s,"no-permission");return true;}if(args.length==0){plugin.messages().list("admin-help").forEach(s::sendMessage);return true;}if(args[0].equalsIgnoreCase("reload")){plugin.reloadAll();plugin.messages().send(s,"reload");return true;}if(args[0].equalsIgnoreCase("list")){s.sendMessage("Активные экспедиции: "+plugin.service().repository().active().size());plugin.service().repository().active().forEach(e->s.sendMessage(e.id()+" — "+e.definitionId()+" — "+e.leaderId()));return true;}if(args.length<2)return true;try{UUID id=UUID.fromString(args[1]);ActiveExpedition e=plugin.service().repository().get(id);if(e==null){plugin.messages().send(s,"expedition-not-found",Map.of("id",id));return true;}if(args[0].equalsIgnoreCase("complete")){plugin.service().finish(e,ExpeditionStatus.COMPLETED);plugin.messages().send(s,"admin-completed");}else if(args[0].equalsIgnoreCase("cancel")){plugin.service().finish(e,ExpeditionStatus.CANCELLED);plugin.messages().send(s,"admin-cancelled");}}catch(IllegalArgumentException ex){plugin.messages().send(s,"expedition-not-found",Map.of("id",args[1]));}return true;}public List<String> onTabComplete(CommandSender s,Command c,String l,String[] a){if(a.length==1)return List.of("list","complete","cancel","reload");if(a.length==2)return plugin.service().repository().active().stream().map(e->e.id().toString()).toList();return List.of();}}
